    guard_evade_ratio={defend=.55,evade=.45}, guard_attack_ratio={defend=.55,attack=.45},
    guard_mixed_ratio={defend=.45,attack=.3,evade=.25}, rookie_guard={defend=.45,attack=.3,evade=.25},
  }
