  local adaptive={
    guard_evade_adaptive={defend=.55,evade=.45}, guard_attack_adaptive={defend=.55,attack=.45},
    guard_mixed_adaptive={defend=.45,attack=.3,evade=.25}, veteran_guard={defend=.45,attack=.3,evade=.25},
  }
  local w=adaptive[strategy]
  if w then
